#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
uniform shader backdrop;
float4 amzSample_comp(float2 uv) { return float4(backdrop.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);if(tex==1) return amzSample_comp(uv);return float4(0.0); }
uniform float amzp_threshold;
uniform float amzp_feather;
uniform float amzp_density;
uniform float amzp_offset;
uniform float amzp_mode;
uniform float amzp_sampling;
        void amzRender() {
            float2 texelSize = 1.0 / getTexSize((screen.zw/1.0));
            float lowCutoff = amzp_threshold-(amzp_threshold*amzp_feather);
            float hiCutoff = amzp_threshold;
            float range = hiCutoff - lowCutoff;
            float pLeft = 0.0;
            float pRight = 0.0;
            float pUp = 0.0;
            float pDown = 0.0;
            float2 velocity;
            velocity = float2(0.1,0.0) * amzp_density;
            velocity *= screen.zw*texelSize;
            velocity.x *= screen.zw.y / screen.zw.x;
            float speed = length(velocity / texelSize);
            int nSamples = int(clamp(speed, 1.01, 30.01));
            for(int i=1; i<nSamples; i++ ) {
                float2 amzp_offset = velocity * (float(i) / float(nSamples - 1) );
                float2 sampleCoord;
                sampleCoord = amzScreenNorm().st+amzp_offset;
                float insideTexture = step(0.0,sampleCoord.x) * step(sampleCoord.x,1.0) * step(0.0,sampleCoord.y) * step(sampleCoord.y,1.0);
                float4 fg = amzTexture(0,sampleCoord) * insideTexture;;
                float4 bg = amzTexture(1,sampleCoord);
                float diff = length(fg.rgb - bg.rgb) * fg.a;
                float t;
                if( int(amzp_sampling) == 0 ) {
                    t = clamp((diff - lowCutoff)/range,0.0,1.0);
                } else {
                    t = smoothstep(lowCutoff,hiCutoff,diff);
                }
                pRight = max(pRight, t);
            }
            for(int i=1; i<nSamples; i++ ) {
                float2 amzp_offset = velocity * (float(i) / float(nSamples - 1) );
                float2 sampleCoord;
                sampleCoord = amzScreenNorm().st-amzp_offset;
                float insideTexture = step(0.0,sampleCoord.x) * step(sampleCoord.x,1.0) * step(0.0,sampleCoord.y) * step(sampleCoord.y,1.0);
                float4 fg = amzTexture(0,sampleCoord) * insideTexture;;
                float4 bg = amzTexture(1,sampleCoord);
                float diff = length(fg.rgb - bg.rgb) * fg.a;
                float t;
                if( int(amzp_sampling) == 0 ) {
                    t = clamp((diff - lowCutoff)/range,0.0,1.0);
                } else {
                    t = smoothstep(lowCutoff,hiCutoff,diff);
                }
                pLeft = max(pLeft, t);
            }
            velocity = float2(0.0,0.1) * amzp_density;
            velocity *= screen.zw * texelSize;
            velocity.x *= screen.zw.y / screen.zw.x;
            speed = length(velocity / texelSize);
            nSamples = int(clamp(speed, 1.01, 30.01));
            for(int i=1; i<nSamples; i++ ) {
                float2 amzp_offset = velocity * (float(i) / float(nSamples - 1) );
                float2 sampleCoord;
                sampleCoord = amzScreenNorm().st+amzp_offset;
                float insideTexture = step(0.0,sampleCoord.x) * step(sampleCoord.x,1.0) * step(0.0,sampleCoord.y) * step(sampleCoord.y,1.0);
                float4 fg = amzTexture(0,sampleCoord) * insideTexture;;
                float4 bg = amzTexture(1,sampleCoord);
                float diff = length(fg.rgb - bg.rgb) * fg.a;
                float t;
                if( int(amzp_sampling) == 0 ) {
                    t = clamp((diff - lowCutoff)/range,0.0,1.0);
                } else {
                    t = smoothstep(lowCutoff,hiCutoff,diff);
                }
                pUp = max(pUp, t);
            }
            for(int i=1; i<nSamples; i++ ) {
                float2 amzp_offset = velocity * (float(i) / float(nSamples - 1) );
                float2 sampleCoord;
                sampleCoord = amzScreenNorm().st-amzp_offset;
                float insideTexture = step(0.0,sampleCoord.x) * step(sampleCoord.x,1.0) * step(0.0,sampleCoord.y) * step(sampleCoord.y,1.0);
                float4 fg = amzTexture(0,sampleCoord) * insideTexture;;
                float4 bg = amzTexture(1,sampleCoord);
                float diff = length(fg.rgb - bg.rgb) * fg.a;
                float t;
                if( int(amzp_sampling) == 0 ) {
                    t = clamp((diff - lowCutoff)/range,0.0,1.0);
                } else {
                    t = smoothstep(lowCutoff,hiCutoff,diff);
                }
                pDown = max(pDown, t);
            }
            float p = max(min(pLeft,pRight), min(pUp,pDown));
            float4 fg = amzTexture(0,amzScreenNorm());
            if( amzp_density < 0.0001 ) {
                float4 bg = amzTexture(1,amzScreenNorm());
                float diff = length(fg.rgb - bg.rgb) * fg.a;
                if( int(amzp_sampling) == 0 ) {
                    p = clamp((diff - lowCutoff)/range,0.0,1.0);
                } else {
                    p = smoothstep(lowCutoff,hiCutoff,diff);
                }
            }
            if( p < amzp_offset ) p = 0.0;
            if( int(amzp_mode)==0 ) {
                amzOutput = fg * p;
            } else if( int(amzp_mode)==1 ) {
                amzOutput = float4(p,p,p,1.0) * fg.a;
            } else if( int(amzp_mode)==2 ) {
                amzOutput = float4(pLeft,pUp,pRight,1.0) * fg.a;
            } else {
                amzOutput = float4(p,p,p,1.0) * fg.a;
            }
        }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
